from __future__ import annotations


def u(id, n, grp, lat, lng, area, rent, prem, floor, was, rec, foot, persona, note):
    return {"id": id, "n": n, "grp": grp, "lat": lat, "lng": lng, "area": area, "rent": rent,
            "prem": prem, "floor": floor, "was": was, "rec": rec, "foot": foot, "persona": persona, "note": note}


def e(id, n, lat, lng, ic, when, k2, desc, roles, ha):
    return {"id": id, "n": n, "lat": lat, "lng": lng, "ic": ic, "when": when, "k2": k2,
            "desc": desc, "roles": roles, "ha": ha}


